const ownerLogin = 'hsimah';
const runnerLogin = 'rodnik';
const forgejoApiBaseUrl = 'https://kennl.loft.hsimah.com/api/v1';
const maximumReviewRounds = 3;
const trustedLabellers = [ownerLogin, runnerLogin];

const labelEvent = $input.first().json.body ?? {};
const pullRequest = labelEvent.pull_request ?? {};
const labelNames = (pullRequest.labels ?? []).map((label) => label.name);

const isReviewRequestFromTrustedLabeller =
  labelEvent.action === 'label_updated' &&
  Number.isInteger(pullRequest.number) &&
  labelNames.includes('agent:review') &&
  !labelNames.includes('agent:reviewing') &&
  trustedLabellers.includes(labelEvent.sender?.login);

if (!isReviewRequestFromTrustedLabeller) {
  return [];
}

return [
  {
    json: {
      ownerLogin,
      runnerLogin,
      trustedLabellers,
      forgejoApiBaseUrl,
      maximumReviewRounds,
      repositoryFullName: labelEvent.repository.full_name,
      pullRequestNumber: pullRequest.number,
    },
  },
];

const labelEvent = $('Read PR label event').first().json;
const pullRequest = $('Get pull request').first().json;
const timelineEvents = $('Get PR timeline').all().map((item) => item.json);
const earlierRunnerReviews = $('Get PR reviews')
  .all()
  .map((item) => item.json)
  .filter((review) => review.user?.login === labelEvent.runnerLogin);
const linkedIssue = $input.first().json;
const currentLabelNames = (pullRequest.labels ?? []).map((label) => label.name);

const latestReviewLabeller = timelineEvents
  .filter((timelineEvent) => timelineEvent.type === 'label' && timelineEvent.label?.name === 'agent:review')
  .at(-1)?.user?.login;

const gateFailures = [];
if (pullRequest.state !== 'open' || pullRequest.merged) {
  gateFailures.push('pull request is not open');
}
if (!String(pullRequest.head?.ref ?? '').startsWith('claude/')) {
  gateFailures.push(`head branch ${pullRequest.head?.ref} is not a claude/ branch`);
}
if (pullRequest.head?.repo?.full_name !== labelEvent.repositoryFullName) {
  gateFailures.push('head branch lives in another repository');
}
if (!currentLabelNames.includes('agent:review')) {
  gateFailures.push('agent:review is no longer on the pull request');
}
if (currentLabelNames.includes('agent:reviewing')) {
  gateFailures.push('pull request is already being reviewed');
}
if (!labelEvent.trustedLabellers.includes(latestReviewLabeller)) {
  gateFailures.push(`agent:review was last added by ${latestReviewLabeller ?? 'nobody'}`);
}

if (gateFailures.length > 0) {
  console.log(`Review gate stopped #${labelEvent.pullRequestNumber}: ${gateFailures.join('; ')}`);
  return [];
}

const reviewRound = earlierRunnerReviews.length + 1;
const reviewRoundsExhausted = reviewRound > labelEvent.maximumReviewRounds;
const linkedIssueIsFromOwner =
  Number.isInteger(linkedIssue.number) && linkedIssue.user?.login === labelEvent.ownerLogin;
const handoffLabelNames = ['agent:review', 'agent:changes', 'agent:human', 'agent:needs-human'];
const unrelatedLabelNames = currentLabelNames.filter((labelName) => !handoffLabelNames.includes(labelName));

return [
  {
    json: {
      ...labelEvent,
      headBranchName: pullRequest.head.ref,
      baseBranchName: pullRequest.base.ref,
      pullRequestTitle: pullRequest.title,
      reviewRound,
      reviewRoundsExhausted,
      linkedIssueText: linkedIssueIsFromOwner
        ? `Issue #${linkedIssue.number}: ${linkedIssue.title}\n\n${linkedIssue.body ?? ''}`
        : '',
      earlierReviewBodies: earlierRunnerReviews.map((review) => review.body ?? ''),
      claimedLabelNames: reviewRoundsExhausted
        ? [...unrelatedLabelNames, 'agent:needs-human']
        : [...unrelatedLabelNames, 'agent:reviewing'],
    },
  },
];

const gatePassed = $('Check review gate').first().json;

if (gatePassed.reviewRoundsExhausted) {
  return [{ json: { ...gatePassed, runReview: false } }];
}

const labelsAfterClaim = $input.all().map((item) => item.json);
if (!labelsAfterClaim.some((label) => label.name === 'agent:reviewing')) {
  throw new Error('agent:reviewing was not applied to the pull request. Check the label exists in the organisation.');
}

const earlierReviewsText = gatePassed.earlierReviewBodies
  .map((reviewBody, reviewIndex) => `--- Review ${reviewIndex + 1} ---\n${reviewBody}`)
  .join('\n\n');

const reviewPrompt = `Review pull request #${gatePassed.pullRequestNumber} in ${gatePassed.repositoryFullName} \
(round ${gatePassed.reviewRound} of ${gatePassed.maximumReviewRounds}).
You are on its branch, ${gatePassed.headBranchName}. The base branch is origin/${gatePassed.baseBranchName}.
The workspace is read-only: you review, you do not change anything.

Read CLAUDE.md if the repository has one. See the change with:
  git log origin/${gatePassed.baseBranchName}..HEAD
  git diff origin/${gatePassed.baseBranchName}...HEAD

The issue this pull request implements (empty if none):
<issue>
${gatePassed.linkedIssueText}
</issue>

Your earlier reviews of this pull request, oldest first (empty on the first round). Check each required change was addressed:
<earlier-reviews>
${earlierReviewsText}
</earlier-reviews>

Request changes only for bugs, requirements of the issue that are not met, or CLAUDE.md violations.
Mention nits, but do not block on them.

Reply with ONLY one JSON object and nothing else, either:
{"verdict": "approve", "review": "<markdown: a short summary of what you checked>"}
or:
{"verdict": "changes", "review": "<markdown: a numbered list of the required changes>"}`;

const encodedPrompt = Buffer.from(reviewPrompt, 'utf8').toString('base64');
const maximumEncodedPromptLength = 100000;
if (encodedPrompt.length > maximumEncodedPromptLength) {
  throw new Error(`Review prompt for #${gatePassed.pullRequestNumber} is too long (${encodedPrompt.length} base64 characters).`);
}

return [
  {
    json: {
      ...gatePassed,
      runReview: true,
      sshCommand: `review ${gatePassed.repositoryFullName} ${gatePassed.headBranchName} ${encodedPrompt}`,
    },
  },
];

const reviewRequest = $('Build review request').first().json;
const sshOutput = $input.first().json;

let runResult;
try {
  runResult = JSON.parse(sshOutput.stdout);
} catch {
  const sshFailureDetail = sshOutput.stderr || sshOutput.error?.message || sshOutput.message || 'no output from rodnik';
  runResult = { is_error: true, outcome: 'ssh-error', reason: String(sshFailureDetail).slice(0, 2000) };
}

let verdictObject = {};
try {
  verdictObject = JSON.parse(String(runResult.result ?? '').replace(/^\s*```.*$/gm, '')) ?? {};
} catch {
  verdictObject = {};
}

const verdict = runResult.outcome === 'reviewed' ? verdictObject.verdict : undefined;
const hasValidVerdict = (verdict === 'approve' || verdict === 'changes') && Boolean(verdictObject.review);
const nextLabelName = !hasValidVerdict ? 'agent:needs-human' : verdict === 'approve' ? 'agent:human' : 'agent:changes';

const verdictHeading = verdict === 'approve' ? 'ready for you' : 'changes needed';
const reviewBody = hasValidVerdict
  ? `**Claude review, round ${reviewRequest.reviewRound} of ${reviewRequest.maximumReviewRounds}: ${verdictHeading}**\n\n${verdictObject.review}`
  : '';

const wasRejectedBeforeClaudeRan = runResult.outcome === 'rejected';
const failureReason =
  runResult.reason ??
  (wasRejectedBeforeClaudeRan ? runResult.result : runResult.outcome === 'reviewed' ? 'The review was not the expected JSON verdict.' : '') ??
  '';
const claudeOutputExcerpt =
  !wasRejectedBeforeClaudeRan && runResult.result
    ? `<details><summary>Claude's final message</summary>\n\n\`\`\`\n${String(runResult.result).slice(0, 4000)}\n\`\`\`\n</details>`
    : '';
const failureComment = [
  `Agent review stopped: **${runResult.outcome ?? 'unknown'}**.`,
  failureReason,
  claudeOutputExcerpt,
  'Add `agent:review` again to retry.',
]
  .filter(Boolean)
  .join('\n\n');

return [
  {
    json: {
      ...reviewRequest,
      reviewOutcome: runResult.outcome ?? 'unknown',
      verdict: verdict ?? null,
      hasValidVerdict,
      nextLabelName,
      reviewBody,
      failureComment,
      reviewersToRequest: verdict === 'approve' && hasValidVerdict ? [reviewRequest.ownerLogin] : [],
    },
  },
];

const reviewResult = $('Read review result').first().json;
const pullRequest = $input.first().json;

const labelNamesWithoutReviewing = (pullRequest.labels ?? [])
  .map((label) => label.name)
  .filter((labelName) => labelName !== 'agent:reviewing');

return [{ json: { finalLabelNames: [...new Set([...labelNamesWithoutReviewing, reviewResult.nextLabelName])] } }];
